-- ===== U7 vocab 覆盖灌库(volume='9',29词)。分步跑。=====

SELECT 'U7 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U7';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U7';
SELECT 'U7 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U7';  -- 应0


SELECT 'U7 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U7';  -- 应29
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U7' GROUP BY word HAVING count(*)>1;  -- 查重应0行